import { useEffect, useState } from "react";
import { getPluginContext } from "../../../plugin-context";
import type { DesignRecord } from "../../../domain/history-store";

/**
 * The blob URL for a raster design, resolved once per id.
 *
 * An `engine: "ai"` record is a PNG in host blob storage. Before this hook the stage
 * re-rendered `renderLogo(spec)` — i.e. a *vector approximation* of a raster mark —
 * so a design generated by the image path looked like nothing the user had seen, or
 * like an unrelated vector. That is the "panel did not sync" symptom.
 */
export function useRasterUrl(record: DesignRecord | undefined): string | null {
	const [url, setUrl] = useState<string | null>(null);
	const blobId = record && record.engine === "ai" ? record.blobId : undefined;

	useEffect(() => {
		if (!blobId) {
			setUrl(null);
			return;
		}
		let alive = true;
		void getPluginContext()
			.storage.getBlobRef(blobId)
			.then((ref) => {
				if (alive) setUrl(ref?.url ?? null);
			})
			.catch(() => {
				if (alive) setUrl(null);
			});
		return () => {
			alive = false;
		};
	}, [blobId]);

	return url;
}
